// failure is the error of the first method, called against a fake that answers with err.
func failure(t *testing.T, api *fake, client *Client, err error) Error {
	t.Helper()
	api.err = err

	response, err := calls[0].do(t.Context(), client, nil)
	e, ok := errors.AsType[*Error](err)
	if !ok || response != nil {
		t.Fatalf("a failed call returned the response %v and the error %#v: want nil and an *Error", response, err)
	}
	return *e
}

func sameError(t *testing.T, got, want Error) {
	t.Helper()
	if where := differ(reflect.ValueOf(got), reflect.ValueOf(want), "the error"); where != "" {
		t.Error(where)
	}
}

// TestErrorCodes: each code the API answers with is the Error's, with its message and
// nothing below it.
func TestErrorCodes(t *testing.T) {
	api, server := serve(t)
	client := clientOf(server, account)

	for code := connect.CodeCanceled; code <= connect.CodeUnauthenticated; code++ {
		got := failure(t, api, client, connect.NewError(code, "why"))
		sameError(t, got, Error{Code: Code(code), Message: "why"})

		name := strings.ToUpper(code.String())
		if got.Code.String() != name || got.Error() != "pethost: "+name+": why" {
			t.Errorf("code %d prints as %q, in the error %q: want %s", code, got.Code, got.Error(), name)
		}
	}
	if got := Code(99).String(); got != "Code(99)" {
		t.Errorf("a code of a later API prints as %q", got)
	}
}

