				want := detail.want(sample)
				want.Code, want.Message = CodeFailedPrecondition, "why"
				sameError(t, failure(t, api, client, connect.NewError(connect.CodeFailedPrecondition, "why").WithDetail(packed)), want)
				if t.Failed() {
					t.FailNow()
				}
