	client := clientOf(server, account)

	cancelled, cancel := context.WithCancel(t.Context())
	cancel()
	_, err := calls[0].do(cancelled, client, nil)
	if e, ok := errors.AsType[*Error](err); !ok || e.Code != CodeCanceled || !errors.Is(err, context.Canceled) {
		t.Errorf("a cancelled context: %#v", err)
	}

