// asks is an HTTP client's transport that sends nothing: it answers each request itself.
type asks func(*http.Request) (*http.Response, error)

func (a asks) RoundTrip(request *http.Request) (*http.Response, error) { return a(request) }

// TestAddress: a client made of a token alone calls the API where it is, over the HTTP client
// it was given.
func TestAddress(t *testing.T) {
	asked := ""
	offline := &http.Client{Transport: asks(func(request *http.Request) (*http.Response, error) {
		asked = request.URL.Scheme + "://" + request.URL.Host
		return nil, errors.New("the check sends nothing")
	})}

	_, err := calls[0].do(t.Context(), NewClient(Config{Token: account, HTTPClient: offline}), nil)
	if e, ok := errors.AsType[*Error](err); !ok || e.Unwrap() == nil {
		t.Errorf("a call that was not sent: %#v", err)
	}
	if want := "https://console.pethost.dev"; asked != want {
		t.Errorf("the call went to %q, want %q", asked, want)
	}
}
